function sheetTable({ values, majorDimension = "ROWS" }) {
  if (
    majorDimension !== "ROWS" ||
    !Array.isArray(values) ||
    values.some((row) => !Array.isArray(row))
  )
    throw Error("Google Sheets must return row-oriented cell values.");
  const isEmpty = (value) => value == null || value === "",
    nonempty = (row) => row.some((value) => !isEmpty(value)),
    headerIndex = values.findIndex(nonempty);
  if (headerIndex < 0) return { columns: [], records: [] };
  const headers = values[headerIndex];
  if (
    headers.some((name) => typeof name !== "string" || !name.trim() || name === "row_number") ||
    new Set(headers).size !== headers.length
  )
    throw Error("Use unique nonempty text headers; row_number is reserved.");
  const columns = ["row_number", ...headers],
    records = [];
  for (let index = headerIndex + 1; index < values.length; index++) {
    const cells = values[index];
    if (!nonempty(cells)) continue;
    if (cells.slice(headers.length).some((value) => !isEmpty(value)))
      throw Error("Every populated column needs a header.");
    records.push(
      Object.fromEntries([
        ["row_number", index + 1],
        ...headers.map((name, column) => [name, cells[column] ?? ""]),
      ]),
    );
  }
  return { columns, records };
}
const reminderMessages = {
  7: (inv) =>
    "היי " +
    inv.name +
    ", תזכורת ידידותית: חשבונית מספר " +
    inv.id +
    " על סך " +
    inv.amount +
    " ₪ ממתינה לתשלום כבר שבוע. נשמח להסדרה בהקדם, תודה!",
  14: (inv) =>
    "שלום " +
    inv.name +
    ", חשבונית מספר " +
    inv.id +
    " על סך " +
    inv.amount +
    " ₪ פתוחה כבר 14 יום. נודה לטיפולך. אם התשלום כבר בוצע, אפשר להתעלם מהודעה זו.",
  30: (inv) =>
    "שלום " +
    inv.name +
    ", תזכורת אחרונה: חשבונית מספר " +
    inv.id +
    " על סך " +
    inv.amount +
    " ₪ פתוחה מזה 30 יום. נבקש להסדיר את התשלום עוד היום. לשאלות אנחנו זמינים כאן.",
};

function invoiceCalendarDate(value, timeZone) {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(value);
  const get = (name) => parts.find((part) => part.type === name).value;
  return get("year") + "-" + get("month") + "-" + get("day");
}

function invoiceDateOrdinal(value, timeZone) {
  if (typeof value !== "string" || !value.trim()) return null;
  const text = value.trim();
  const ordinal = (year, month, day) => {
    const date = new Date(Date.UTC(year, month - 1, day));
    return date.getUTCFullYear() === year &&
      date.getUTCMonth() === month - 1 &&
      date.getUTCDate() === day
      ? date.getTime() / 86400000
      : null;
  };
  const iso = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text);
  if (iso) return ordinal(Number(iso[1]), Number(iso[2]), Number(iso[3]));
  const timestamp =
    /^(\d{4})-(\d{2})-(\d{2})T(?:[01]\d|2[0-3]):[0-5]\d(?::[0-5]\d(?:\.\d{1,9})?)?(?:Z|[+-](?:[01]\d|2[0-3]):?[0-5]\d)$/.exec(
      text,
    );
  if (
    timestamp &&
    ordinal(Number(timestamp[1]), Number(timestamp[2]), Number(timestamp[3])) !== null
  ) {
    const date = new Date(text);
    if (!Number.isFinite(date.getTime())) return null;
    return invoiceDateOrdinal(invoiceCalendarDate(date, timeZone), timeZone);
  }
  const slash = /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec(text);
  if (!slash) return null;
  return (
    ordinal(Number(slash[3]), Number(slash[2]), Number(slash[1])) ??
    ordinal(Number(slash[3]), Number(slash[1]), Number(slash[2]))
  );
}

function invoiceIdentity(value) {
  if (typeof value !== "string" && !(typeof value === "number" && Number.isFinite(value)))
    throw new Error("Use nonempty text or numeric InvoiceID values.");
  const id = String(value).trim();
  if (!id) throw new Error("Use a nonempty InvoiceID.");
  return id;
}

function invoiceChatId(value) {
  if (typeof value === "number" && (!Number.isSafeInteger(value) || value <= 0))
    throw new Error("Use a valid customer phone number.");
  if (
    (typeof value !== "string" && typeof value !== "number") ||
    !/^[+\d\s().-]+$/.test(String(value))
  )
    throw new Error("Use an Israeli customer phone number.");
  let digits = String(value).replace(/\D/g, "");
  if (digits.startsWith("0")) digits = "972" + digits.slice(1);
  if (!digits.startsWith("972")) digits = "972" + digits;
  if (!/^972[2-9]\d{7,8}$/.test(digits))
    throw new Error("Use an Israeli national number or a number with the 972 country code.");
  return digits + "@c.us";
}

function planInvoiceReminders({ rows, today, timeZone }) {
  const current = invoiceDateOrdinal(today, timeZone);
  if (!Array.isArray(rows) || current === null)
    throw new Error("Provide invoice rows and the processing calendar date.");
  const reminders = [];
  const idCounts = new Map();
  for (const row of rows) {
    try {
      const id = invoiceIdentity(row?.InvoiceID);
      idCounts.set(id, (idCounts.get(id) ?? 0) + 1);
    } catch {}
  }
  let invalidDates = 0;
  for (const row of rows) {
    if (!row || row.Status !== "open") continue;
    const due = invoiceDateOrdinal(row.DueDate, timeZone);
    if (due === null) {
      invalidDates++;
      continue;
    }
    const daysOverdue = current - due,
      message = reminderMessages[daysOverdue];
    if (!message) continue;
    const InvoiceID = invoiceIdentity(row.InvoiceID);
    if (idCounts.get(InvoiceID) !== 1)
      throw new Error("Each selected InvoiceID must identify exactly one sheet row.");
    const name = row.CustomerName ?? "",
      amount = row.Amount ?? "";
    if (
      !["string", "number"].includes(typeof name) ||
      !["string", "number"].includes(typeof amount)
    )
      throw new Error("CustomerName and Amount must be text or numbers.");
    reminders.push({
      InvoiceID,
      tier: "reminder-" + daysOverdue,
      daysOverdue,
      date: today,
      chatId: invoiceChatId(row.Phone),
      message: message({ id: InvoiceID, name, amount }),
    });
  }
  return { reminders, invalidDates, selectedCount: reminders.length };
}

export default function (input) {
  const table = sheetTable(input);
  const expected = [
    "InvoiceID",
    "CustomerName",
    "Amount",
    "DueDate",
    "Phone",
    "Status",
    "LastReminder",
    "LastReminderDate",
  ];
  if (table.columns.length && expected.some((name) => !table.columns.includes(name)))
    throw new Error("The required invoice columns are missing.");
  return planInvoiceReminders({
    rows: table.records,
    today: input.today,
    timeZone: input.timeZone,
  });
}

