export default function collectInvoiceReminders({ reminders, previousState, receipt }) {
  if (!Array.isArray(reminders))
    throw new Error("Expected the validated invoice reminder collection.");
  let state;
  if (previousState === null) {
    if (receipt !== null) throw new Error("Unexpected receipt before invoice processing starts.");
    state = { index: 0, receipts: [] };
  } else {
    if (
      !Number.isSafeInteger(previousState.index) ||
      previousState.index < 0 ||
      previousState.index >= reminders.length ||
      !Array.isArray(previousState.receipts) ||
      previousState.receipts.length !== previousState.index
    )
      throw new Error("Invalid invoice reminder collection state.");
    const reminder = reminders[previousState.index];
    if (receipt?.InvoiceID !== reminder.InvoiceID || receipt.tier !== reminder.tier)
      throw new Error("The reminder receipt does not match this invoice.");
    state = { index: previousState.index + 1, receipts: [...previousState.receipts, receipt] };
  }
  return {
    state,
    index: state.index,
    more: state.index < reminders.length,
    needsPause: state.index > 0,
    sentCount: state.index,
  };
}

