export async function sendOneInvoiceReminder({ reminders, index, spreadsheetId, range }, context) {
  if (
    !Array.isArray(reminders) ||
    !Number.isSafeInteger(index) ||
    index < 0 ||
    index >= reminders.length
  )
    throw new Error("A selected invoice is required.");
  context.signal?.throwIfAborted();
  const reminder = reminders[index];
  const result = await context.workflows.call("send-and-log-invoice-reminder", {
    reminder,
    spreadsheetId,
    range,
  });
  if (result?.receipt?.InvoiceID !== reminder.InvoiceID || result.receipt.tier !== reminder.tier)
    throw new Error("The reminder receipt does not match this invoice.");
  return { receipt: result.receipt };
}
export default async function run(input, context) {
  return sendOneInvoiceReminder(input, context);
}

