export default function prepareWhatsAppInvoiceDelivery({ reminder, endpoint, session }) {
  // The native secure Code VM has no URL global. The host/path are deployment configuration.
  if (
    typeof endpoint !== "string" ||
    !/^https:\/\/[a-zA-Z0-9.-]+(?::\d+)?\/api\/sendText$/.test(endpoint) ||
    /(?:^|[/.])(?:localhost|example)(?:[/:.]|$)/i.test(endpoint) ||
    endpoint.includes("YOUR_")
  )
    throw new Error("Configure your HTTPS WAHA /api/sendText endpoint.");
  if (typeof session !== "string" || !session.trim())
    throw new Error("Configure your WAHA session.");
  if (
    !reminder ||
    !/^972[2-9]\d{7,8}@c\.us$/.test(reminder.chatId) ||
    typeof reminder.message !== "string" ||
    !reminder.message
  )
    throw new Error("Provide a validated invoice reminder.");
  return {
    endpoint,
    payload: { session: session.trim(), chatId: reminder.chatId, text: reminder.message },
  };
}

