export default function verifyWhatsAppInvoiceAcceptance({ body, statusCode }) {
  if (
    statusCode !== 201 ||
    !body ||
    typeof body !== "object" ||
    Array.isArray(body) ||
    typeof body.id !== "string" ||
    !body.id.trim() ||
    body.fromMe !== true ||
    body.ack === -1
  )
    throw new Error("WAHA did not confirm acceptance of the reminder.");
  return { messageId: body.id };
}

