export default function buildInvoiceReminderLog({ values, majorDimension, range, reminder }) {
  const { columns, records } = sheetTable({ values, majorDimension });
  const required = ["InvoiceID", "LastReminder", "LastReminderDate"];
  if (required.some((name) => !columns.includes(name)))
    throw new Error("The invoice log columns are missing.");
  const matches = records.filter((row) => {
    try {
      return invoiceIdentity(row.InvoiceID) === reminder.InvoiceID;
    } catch {
      return false;
    }
  });
  if (matches.length !== 1)
    throw new Error("The sent invoice no longer identifies exactly one row.");
  const columnName = (zeroBased) => {
    let index = zeroBased + 1,
      name = "";
    while (index > 0) {
      index--;
      name = String.fromCharCode(65 + (index % 26)) + name;
      index = Math.floor(index / 26);
    }
    return name;
  };
  const data = ["LastReminder", "LastReminderDate"].map((name) => ({
    range: range + "!" + columnName(columns.indexOf(name) - 1) + matches[0].row_number,
    majorDimension: "ROWS",
    values: [[name === "LastReminder" ? reminder.tier : reminder.date]],
  }));
  return { data };
}

